--
-- Table structure for table `conversations`
--

DROP TABLE IF EXISTS `conversations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conversations` (
  `conversation_id` int NOT NULL AUTO_INCREMENT,
  `client_id` int NOT NULL,
  `status` enum('bot','queued','assigned','in_progress','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bot',
  `priority` enum('low','normal','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `department` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `queue_id` int DEFAULT NULL,
  `assigned_operator_id` int DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `rating` int DEFAULT NULL,
  `rating_comment` text COLLATE utf8mb4_unicode_ci,
  `closed_at` timestamp NULL DEFAULT NULL,
  `closed_by_type` enum('client','operator') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `closed_by_operator_id` int DEFAULT NULL,
  `queued_at` timestamp NULL DEFAULT NULL,
  `assigned_at` timestamp NULL DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`conversation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

