INSERT INTO `messages` VALUES (1,1,'bot',NULL,'Здравствуйте, Test! Я виртуальный помощник. Чем могу помочь?','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:01:46.222599'),(2,1,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Интернет не работает\", \"Оплата\", \"Тарифы\", \"Соединить с оператором\"]}]','2026-01-11 12:27:44',NULL,'2026-01-10 14:01:46.249609'),(3,1,'client',1,'ты кто ??','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:13.948583'),(4,1,'bot',NULL,'Пожалуйста, опишите ваш вопрос подробнее. Или выберите один из вариантов:','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:13.987903'),(5,1,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Интернет не работает\", \"Медленный интернет\", \"Оплата\", \"Тарифы\", \"Соединить с оператором\"]}]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:14.007065'),(6,1,'client',1,'Интернет не работает','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:24.766570'),(7,1,'bot',NULL,'Проверьте следующее:\n1. Роутер включен и индикаторы горят\n2. Кабель подключен правильно\n3. Перезагрузите роутер (выключите на 30 сек)\n4. Проверьте баланс\n\nЕсли не помогло, опишите проблему подробнее.','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:24.795622'),(8,1,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Не помогло\", \"Соединить с оператором\"]}]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:24.815677'),(9,1,'client',1,'Не помогло','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:31.695990'),(10,1,'bot',NULL,'Понял ваш вопрос. Давайте уточним детали. Могу помочь с тарифами, оплатой, подключением или техническими проблемами. Что именно вас интересует?','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:31.740103'),(11,1,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Интернет не работает\", \"Оплата\", \"Тарифы\", \"Соединить с оператором\"]}]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:31.758034'),(12,1,'client',1,'Оплата','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:44.019417'),(13,1,'bot',NULL,'Способы оплаты:\n• Онлайн через мобильное приложение\n• Терминалы оплаты\n• Банковский перевод\n• Наличными в офисе\n\nНужна помощь с оплатой?','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:44.076134'),(14,1,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Соединить с оператором\"]}]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:44.113520'),(15,1,'client',1,'Соединить с оператором','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:53.153169'),(16,1,'system',NULL,'Диалог передан оператору. Пожалуйста, подождите.','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:53.238530'),(17,1,'bot',NULL,'Передаю оператору. Обычно ответ занимает несколько минут. Пожалуйста, оставайтесь в чате.','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:53.255031'),(18,1,'system',NULL,'Сейчас операторов нет онлайн. Оставьте сообщение — мы ответим, как только будем на связи.','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:02:53.317482'),(19,1,'system',NULL,'Оператор Администратор подключился к разговору.','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:11:58.757793'),(20,1,'operator',1,'Салом','[]',NULL,'2026-01-10 09:12:12','2026-01-10 14:12:11.579996'),(21,1,'operator',1,'ба шумо чи кумак кунам ?','[]',NULL,'2026-01-10 09:12:29','2026-01-10 14:12:29.221813'),(22,1,'client',1,'ту ки??','[]','2026-01-11 12:27:44',NULL,'2026-01-10 14:12:54.731099'),(23,1,'operator',1,'1','[]',NULL,'2026-01-10 09:13:58','2026-01-10 14:13:58.313425'),(24,2,'bot',NULL,'Здравствуйте, Test! Я виртуальный помощник. Чем могу помочь?','[]','2026-01-11 12:28:40',NULL,'2026-01-11 17:27:25.983718'),(25,2,'bot',NULL,'Выберите вариант:','[{\"type\": \"buttons\", \"buttons\": [\"Интернет не работает\", \"Оплата\", \"Тарифы\", \"Соединить с оператором\"]}]','2026-01-11 12:28:40',NULL,'2026-01-11 17:27:26.001325'),(26,2,'client',2,'Соединить с оператором','[]','2026-01-11 12:28:40',NULL,'2026-01-11 17:28:16.740742'),(27,2,'syste